                        font.bold: true
                    }
                    RowLayout {
                        Layout.fillWidth: true
                        spacing: 4
                        Button {
                            text: qsTr("Femur…")
                            enabled: !optimizerBridge.running
                            onClicked: segFemPtDialog.open()
                        }
                        Label {
                            Layout.fillWidth: true
                            elide: Text.ElideMiddle
