                                  : qsTr("not set")
                        }
                    }
                    RowLayout {
                        Layout.fillWidth: true
                        spacing: 4
                        Button {
                            text: qsTr("Tibia…")
                            enabled: !optimizerBridge.running
                            onClicked: segTibPtDialog.open()
                        }
                        Label {
                            Layout.fillWidth: true
                            elide: Text.ElideMiddle
                            color: mlBridge.segmentTibPt.length > 0
